/* ========================================
   Bean & Brew - Premium Coffee Shop
   CSS Stylesheet
   ======================================== */

/* Reset & Base Styles */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

:root {
    /* Colors */
    --primary-color: #6F4E37;
    --secondary-color: #C4915B;
    --accent-color: #E8C6A3;
    --dark-color: #2C241F;
    --light-color: #FDFBF7;
    --white: #ffffff;
    --gray-100: #f5f5f5;
    --gray-300: #e0e0e0;
    --gray-700: #757575;
    --gray-900: #212121;

    /* Spacing */
    --spacing-xs: 0.5rem;
    --spacing-sm: 1rem;
    --spacing-md: 2rem;
    --spacing-lg: 4rem;
    --spacing-xl: 6rem;

    /* Typography */
    --font-heading: 'Playfair Display', serif;
    --font-body: 'Poppins', sans-serif;

    /* Transitions */
    --transition-fast: 0.3s ease;
    --transition-normal: 0.5s ease;
}

html {
    font-size: 16px;
    scroll-behavior: smooth;
}

body {
    font-family: var(--font-body);
    font-weight: 400;
    font-size: 1rem;
    line-height: 1.7;
    color: var(--dark-color);
    background-color: var(--light-color);
}

h1, h2, h3, h4, h5, h6 {
    font-family: var(--font-heading);
    font-weight: 700;
    line-height: 1.3;
    color: var(--dark-color);
}

a {
    text-decoration: none;
    color: var(--primary-color);
    transition: var(--transition-fast);
}

a:hover {
    color: var(--secondary-color);
}

img {
    max-width: 100%;
    height: auto;
}

.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-md);
}

/* ========================================
   Utility Classes
   ======================================== */

.text-center {
    text-align: center;
}

.lead {
    font-size: 1.15rem;
    color: var(--gray-700);
    margin-bottom: var(--spacing-md);
}

/* Buttons */
.btn {
    display: inline-block;
    padding: 1rem 2rem;
    font-size: 1rem;
    font-weight: 500;
    font-family: var(--font-body);
    text-transform: uppercase;
    letter-spacing: 1px;
    border: 2px solid transparent;
    cursor: pointer;
    transition: var(--transition-fast);
}

.btn-primary {
    background-color: var(--primary-color);
    color: var(--white);
    border-color: var(--primary-color);
}

.btn-primary:hover {
    background-color: var(--dark-color);
    border-color: var(--dark-color);
    color: var(--white);
}

.btn-secondary {
    background-color: transparent;
    color: var(--white);
    border-color: var(--white);
}

.btn-secondary:hover {
    background-color: var(--white);
    color: var(--primary-color);
}

/* ========================================
   Navigation
   ======================================== */

.navbar {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    padding: 1.25rem var(--spacing-sm);
    background-color: transparent;
    z-index: 1000;
    transition: var(--transition-fast);
}

.navbar.scrolled {
    background-color: var(--dark-color);
    padding: 1rem var(--spacing-sm);
    box-shadow: 0 2px 20px rgba(0, 0, 0, 0.1);
}

.navbar .container {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.nav-brand {
    display: flex;
    align-items: center;
    gap: var(--spacing-xs);
    font-family: var(--font-heading);
    font-size: 1.5rem;
    font-weight: 700;
    color: var(--white);
}

.nav-brand i {
    color: var(--secondary-color);
}

.nav-menu {
    display: flex;
    list-style: none;
    gap: var(--spacing-md);
}

.nav-menu a {
    color: var(--white);
    font-weight: 500;
    font-size: 0.9rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    padding: var(--spacing-xs) 0;
    position: relative;
}

.nav-menu a::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
    width: 0;
    height: 2px;
    background-color: var(--secondary-color);
    transition: var(--transition-fast);
}

.nav-menu a:hover::after,
.nav-menu a.active::after {
    width: 100%;
}

.nav-toggle {
    display: none;
    color: var(--white);
    font-size: 1.5rem;
    cursor: pointer;
}

/* ========================================
   Hero Section
   ======================================== */

.hero {
    position: relative;
    height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(rgba(44, 36, 31, 0.6), rgba(44, 36, 31, 0.6)),
                url('https://images.unsplash.com/photo-1497935586351-b67a49e012bf?w=1920') center/cover;
    min-height: 500px;
}

.hero-overlay {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: rgba(0, 0, 0, 0.4);
}

.hero .container {
    position: relative;
}

.hero-content {
    text-align: center;
    color: var(--white);
    max-width: 800px;
}

.hero-subtitle {
    font-size: 1rem;
    text-transform: uppercase;
    letter-spacing: 3px;
    margin-bottom: var(--spacing-sm);
}

.hero-title {
    font-size: clamp(2.5rem, 5vw, 4rem);
    margin-bottom: var(--spacing-sm);
}

.hero-title .highlight {
    color: var(--secondary-color);
}

.hero-description {
    font-size: 1.2rem;
    margin-bottom: var(--spacing-lg);
}

.hero-description p {
    margin: 0;
}

/* ========================================
   Features Section
   ======================================== */

.features {
    padding: var(--spacing-lg) 0;
    background-color: var(--light-color);
}

.features-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: var(--spacing-md);
}

.feature-card {
    background-color: var(--white);
    padding: var(--spacing-lg);
    text-align: center;
    border-radius: 8px;
    box-shadow: 0 5px 30px rgba(0, 0, 0, 0.08);
    transition: var(--transition-fast);
}

.feature-card:hover {
    transform: translateY(-5px);
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.12);
}

.feature-icon {
    width: 80px;
    height: 80px;
    margin: 0 auto var(--spacing-md);
    display: flex;
    align-items: center;
    justify-content: center;
    background-color: rgba(204, 145, 91, 0.1);
    color: var(--primary-color);
    font-size: 2rem;
    border-radius: 50%;
    transition: var(--transition-fast);
}

.feature-card:hover .feature-icon {
    background-color: var(--primary-color);
    color: var(--white);
    transform: scale(1.1);
}

.feature-card h3 {
    font-size: 1.4rem;
    margin-bottom: var(--spacing-sm);
}

.feature-card p {
    font-size: 1rem;
    color: var(--gray-700);
}

/* ========================================
   About Section
   ======================================== */

.about {
    padding: var(--spacing-xl) 0;
    background-color: var(--primary-color);
    color: var(--white);
}

.about .section-title {
    color: var(--white);
    text-align: center;
    margin-bottom: var(--spacing-sm);
}

.about-content {
    display: flex;
    align-items: center;
    gap: var(--spacing-xl);
}

.about-text {
    flex: 1;
    max-width: 600px;
}

.about-text h2 {
    color: var(--white);
    font-size: 2.5rem;
    text-align: center;
}

.about-text .lead {
    color: rgba(255, 255, 255, 0.9);
    text-align: center;
    font-size: 1.2rem;
    line-height: 1.8;
}

.about-text p {
    color: rgba(255, 255, 255, 0.9);
    margin-bottom: 1rem;
    font-size: 1.05rem;
}

.about-image {
    flex: 1;
    min-width: 300px;
    display: flex;
    justify-content: center;
    align-items: center;
}

.img-wrapper {
    width: 100%;
    max-width: 400px;
    height: 400px;
    background: linear-gradient(rgba(204, 145, 91, 0.3), rgba(216, 184, 141, 0.3)),
                url('https://images.unsplash.com/photo-1514432324607-a09d9b4aefdd?w=600') center/cover;
    border-radius: 10px;
    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.2);
    display: flex;
    align-items: center;
    justify-content: center;
    transition: var(--transition-normal);
}

.img-wrapper i {
    font-size: 8rem;
    color: var(--white);
    text-shadow: 0 5px 30px rgba(0, 0, 0, 0.3);
}

.img-wrapper:hover {
    transform: scale(1.02);
}

.about-stats {
    display: flex;
    justify-content: center;
    gap: var(--spacing-lg);
    margin-top: var(--spacing-md);
    flex-wrap: wrap;
}

.stat-item {
    text-align: center;
}

.stat-number {
    display: block;
    font-size: 2.5rem;
    font-weight: 700;
    font-family: var(--font-heading);
    color: var(--secondary-color);
}

.stat-label {
    font-size: 0.9rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-top: var(--spacing-xs);
    color: rgba(255, 255, 255, 0.8);
}

/* ========================================
   Menu Section
   ======================================== */

.menu {
    padding: var(--spacing-xl) 0;
    background-color: var(--light-color);
}

.menu .section-title {
    font-size: 2.5rem;
    text-align: center;
    margin-bottom: var(--spacing-xs);
}

.section-subtitle {
    font-size: 1.1rem;
    color: var(--gray-700);
    text-align: center;
    margin-bottom: var(--spacing-lg);
}

/* Menu Tabs */
.menu-tabs {
    display: flex;
    justify-content: center;
    gap: var(--spacing-sm);
    margin-bottom: var(--spacing-lg);
    flex-wrap: wrap;
}

.tab-btn {
    padding: 0.75rem 1.5rem;
    font-size: 0.95rem;
    font-weight: 500;
    background-color: transparent;
    border: 2px solid var(--primary-color);
    color: var(--dark-color);
    cursor: pointer;
    transition: var(--transition-fast);
    text-transform: capitalize;
    border-radius: 30px;
}

.tab-btn:hover,
.tab-btn.active {
    background-color: var(--primary-color);
    color: var(--white);
}

/* Menu Content */
.menu-content {
    max-width: 900px;
    margin: 0 auto;
}

.tab-content {
    display: none;
}

.tab-content.active {
    display: block;
    animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
    from {
        opacity: 0;
        transform: translateY(10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* Menu Items Grid */
.menu-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    gap: var(--spacing-md);
}

.menu-item {
    background-color: var(--white);
    border-radius: 8px;
    padding: var(--spacing-md);
    box-shadow: 0 3px 15px rgba(0, 0, 0, 0.06);
    transition: var(--transition-fast);
}

.menu-item:hover {
    box-shadow: 0 5px 25px rgba(0, 0, 0, 0.1);
}

.menu-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    margin-bottom: var(--spacing-sm);
}

.menu-header h3 {
    font-size: 1.2rem;
    margin-bottom: 0.5rem;
    flex: 1;
}

.menu-price {
    font-size: 1.1rem;
    font-weight: 700;
    color: var(--primary-color);
    margin-bottom: 0.5rem;
}

.menu-description {
    font-size: 0.9rem;
    color: var(--gray-700);
    line-height: 1.5;
}

.menu-tags {
    margin-top: var(--spacing-sm);
    display: flex;
    gap: var(--spacing-xs);
    flex-wrap: wrap;
}

.tag {
    padding: 0.25rem 0.75rem;
    font-size: 0.75rem;
    background-color: var(--gray-100);
    color: var(--gray-700);
    border-radius: 15px;
}

.tag.vegan {
    background-color: #e8f5e9;
    color: #2e7d32;
}

.tag.gluten-free {
    background-color: #fff3e0;
    color: #ef6c00;
}

.tag.caffeine-free {
    background-color: #e3f2fd;
    color: #1565c0;
}

/* Menu Footer */
.menu-footer {
    text-align: center;
    padding: var(--spacing-lg) 0;
}

/* ========================================
   Gallery Section
   ======================================== */

.gallery {
    padding: var(--spacing-xl) 0;
    background-color: var(--white);
}

.gallery-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: var(--spacing-sm);
}

.gallery-item {
    position: relative;
    aspect-ratio: 1;
    overflow: hidden;
    cursor: pointer;
}

.gallery-item img,
.gallery-item::before {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.gallery-item::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: linear-gradient(to top, rgba(0, 0, 0, 0.4), transparent);
}

.gallery-overlay {
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    padding: var(--spacing-sm);
    color: var(--white);
    font-size: 0.85rem;
    text-align: center;
    opacity: 0;
    transition: var(--transition-fast);
}

.gallery-item:hover .gallery-overlay {
    opacity: 1;
}

.gallery-item:hover img,
.gallery-item:hover::before {
    transform: scale(1.1);
}

/* ========================================
   Location Section
   ======================================== */

.location {
    padding: var(--spacing-xl) 0;
    background-color: var(--primary-color);
    color: var(--white);
}

.location .container {
    display: flex;
    gap: var(--spacing-lg);
    align-items: stretch;
}

.location-content {
    flex: 1;
    max-width: 600px;
}

.location .section-title {
    color: var(--white);
    text-align: left;
    margin-bottom: var(--spacing-md);
}

.info-item {
    display: flex;
    gap: var(--spacing-sm);
    margin-bottom: var(--spacing-md);
}

.info-item i {
    font-size: 1.2rem;
    color: var(--secondary-color);
    margin-top: 0.25rem;
    flex-shrink: 0;
}

.info-item h4 {
    color: var(--white);
    font-size: 1rem;
    margin-bottom: 0.25rem;
}

.info-item p {
    color: rgba(255, 255, 255, 0.85);
    font-size: 0.95rem;
}

.map-placeholder {
    flex: 1;
    min-height: 400px;
    background-color: rgba(255, 255, 255, 0.1);
    border: 2px dashed rgba(255, 255, 255, 0.3);
    border-radius: 8px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    color: rgba(255, 255, 255, 0.6);
}

.map-placeholder i {
    font-size: 3rem;
    margin-bottom: var(--spacing-sm);
}

.map-placeholder span {
    font-size: 1.1rem;
}

/* ========================================
   Newsletter Section
   ======================================== */

.newsletter {
    padding: var(--spacing-lg) 0;
    background-color: var(--secondary-color);
    position: relative;
    overflow: hidden;
}

.newsletter::before {
    content: '';
    position: absolute;
    top: -50%;
    left: -50%;
    width: 200%;
    height: 200%;
    background: radial-gradient(circle, rgba(255, 255, 255, 0.1) 1px, transparent 1px);
    background-size: 30px 30px;
    animation: gridMove 60s linear infinite;
}

.newsletter-content {
    position: relative;
    text-align: center;
    max-width: 600px;
    margin: 0 auto;
}

.newsletter h3 {
    color: var(--white);
    font-size: 2rem;
    margin-bottom: var(--spacing-sm);
}

.newsletter p {
    color: rgba(255, 255, 255, 0.9);
    font-size: 1.1rem;
    margin-bottom: var(--spacing-md);
}

.newsletter-form {
    display: flex;
    gap: var(--spacing-sm);
    justify-content: center;
    max-width: 450px;
    margin: 0 auto;
}

.newsletter-form input {
    flex: 1;
    padding: 1rem 1.25rem;
    font-size: 1rem;
    border: none;
    border-radius: 30px;
    outline: none;
    width: 100%;
}

.newsletter-form input::placeholder {
    color: var(--gray-300);
}

.newsletter-form button {
    white-space: nowrap;
    width: auto;
    padding: 1rem 2rem;
}

@keyframes gridMove {
    from {
        transform: translate(0, 0);
    }
    to {
        transform: translate(30px, 30px);
    }
}

/* ========================================
   Footer
   ======================================== */

.footer {
    background-color: var(--dark-color);
    color: rgba(255, 255, 255, 0.8);
    padding: var(--spacing-xl) 0 var(--spacing-md);
}

.footer-content {
    display: grid;
    grid-template-columns: 1.5fr 1fr;
    gap: var(--spacing-xl);
    margin-bottom: var(--spacing-lg);
}

.footer-brand {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-sm);
}

.footer-logo {
    display: flex;
    align-items: center;
    gap: var(--spacing-xs);
    font-family: var(--font-heading);
    font-size: 1.5rem;
    color: var(--white);
}

.footer-logo i {
    color: var(--secondary-color);
}

.footer-brand p {
    font-size: 0.95rem;
    color: rgba(255, 255, 255, 0.7);
}

.social-links {
    display: flex;
    gap: var(--spacing-sm);
    margin-top: var(--spacing-sm);
}

.social-link {
    width: 40px;
    height: 40px;
    display: flex;
    align-items: center;
    justify-content: center;
    background-color: rgba(255, 255, 255, 0.1);
    color: var(--white);
    border-radius: 50%;
    transition: var(--transition-fast);
}

.social-link:hover {
    background-color: var(--secondary-color);
}

.footer-column h4 {
    color: var(--white);
    font-size: 1rem;
    margin-bottom: var(--spacing-sm);
}

.footer-column ul {
    list-style: none;
}

.footer-column ul li {
    margin-bottom: 0.75rem;
}

.footer-column ul li a {
    color: rgba(255, 255, 255, 0.7);
    font-size: 0.95rem;
    transition: var(--transition-fast);
}

.footer-column ul li a:hover {
    color: var(--secondary-color);
    padding-left: 5px;
}

.footer-bottom {
    padding-top: var(--spacing-md);
    border-top: 1px solid rgba(255, 255, 255, 0.1);
    text-align: center;
}

.footer-bottom p {
    font-size: 0.9rem;
}

/* ========================================
   Responsive Design
   ======================================== */

@media (max-width: 992px) {
    .about-content {
        flex-direction: column;
        text-align: center;
    }

    .about-text {
        max-width: 100%;
    }

    .about-text .lead {
        text-align: left;
    }

    .about-stats {
        justify-content: flex-start;
    }

    .location-content {
        max-width: 100%;
    }

    .location-content,
    .map-placeholder {
        flex: none;
        width: 100%;
    }

    .newsletter-form {
        flex-direction: column;
    }

    .newsletter-form input {
        width: 100%;
    }

    .footer-content {
        grid-template-columns: 1fr;
        text-align: center;
    }

    .footer-brand {
        align-items: center;
    }

    .social-links {
        justify-content: center;
    }
}

@media (max-width: 768px) {
    :root {
        --spacing-lg: 3rem;
        --spacing-xl: 4rem;
    }

    .nav-menu {
        position: fixed;
        top: 60px;
        left: -100%;
        width: 100%;
        flex-direction: column;
        background-color: var(--dark-color);
        padding: var(--spacing-md);
        gap: var(--spacing-sm);
        transition: var(--transition-normal);
    }

    .nav-menu.active {
        left: 0;
    }

    .nav-toggle {
        display: block;
    }

    .hero {
        min-height: 60vh;
    }

    .hero-title {
        font-size: 2rem;
    }

    .features-grid {
        grid-template-columns: 1fr;
    }

    .menu-tabs {
        overflow-x: auto;
        flex-wrap: nowrap;
        justify-content: flex-start;
        padding-bottom: var(--spacing-sm);
    }

    .tab-btn {
        white-space: nowrap;
    }

    .menu-grid {
        grid-template-columns: 1fr;
    }

    .gallery {
        text-align: center;
    }

    .gallery-grid {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (max-width: 480px) {
    .hero {
        min-height: 50vh;
        text-align: center;
    }

    .hero-title {
        font-size: 1.75rem;
    }

    .hero-description {
        font-size: 1.1rem;
    }

    .about-stats {
        flex-direction: column;
        gap: var(--spacing-sm);
    }

    .img-wrapper {
        height: 300px;
    }

    .img-wrapper i {
        font-size: 6rem;
    }

    .gallery-grid {
        grid-template-columns: 1fr;
    }

    .nav-brand {
        font-size: 1.25rem;
    }

    .section-title {
        font-size: 1.8rem;
    }
}

/* ========================================
   Animations
   ======================================== */

@keyframes fadeInUp {
    from {
        opacity: 0;
        transform: translateY(30px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.animate-on-scroll {
    opacity: 0;
}

.animate-on-scroll.animate {
    animation: fadeInUp 0.6s ease forwards;
}

/* Smooth scroll for anchor links */
a[href^="#"] {
    scroll-margin-top: 100px;
}
